    @Test
    public void testGetSchema_SerializeAsIndexTrue() throws Exception {
        // Arrange
        EnumSerializer serializer = Mockito.spy(new EnumSerializer(mockEnumValues()));
        // Force _serializeAsIndex to return true
        // Since _serializeAsIndex is protected, we use Mockito spy to stub it
        when(serializer.getSchema(any(), any())).thenCallRealMethod();
        // We need to bypass the private/protected check. 
        // Because _serializeAsIndex is protected, we can't easily override it without a subclass.

        class TestSerializer extends EnumSerializer {
            private final boolean index;
            public TestSerializer(EnumValues v, boolean index) { super(v); this.index = index; }
            @Override
            protected boolean _serializeAsIndex(SerializerProvider provider) { return index; }
        }

        TestSerializer testSerializer = new TestSerializer(mockEnumValues(), true);

        // Act
        JsonNode result = testSerializer.getSchema(provider, null);

        // Assert
        assertNotNull(result);
        assertEquals("integer", result.get("type").asText());
        assertTrue(result.get("integer").asBoolean());
    }

    @Test
