        // Assert
        assertNotNull(result);
        assertEquals("string", result.get("type").asText());
        assertTrue(result.get("string").asBoolean());
        assertFalse(result.has("enum"));
    }

    @Test
    public void testGetSchema_SerializeAsIndexFalse_TypeHintNotEnum() throws Exception {
        // Arrange
        class TestSerializer extends EnumSerializer {
            public TestSerializer(EnumValues v) { super(v); }
            @Override
            protected boolean _serializeAsIndex(SerializerProvider provider) { return false; }
        }
        TestSerializer testSerializer = new TestSerializer(mockEnumValues());

        JavaType nonEnumType = Mockito.mock(JavaType.class);
        when(nonEnumType.isEnumType()).thenReturn(false);
        when(provider.constructType(any())).thenReturn(nonEnumType);

        // Act
        JsonNode result = testSerializer.getSchema(provider, TestEnum.class);

        // Assert
        assertNotNull(result);
        assertEquals("string", result.get("type").asText());
        assertFalse(result.has("enum"));
    }

    @Test
    public void testGetSchema_SerializeAsIndexFalse_TypeHintIsEnum() throws Exception {
        // Arrange
        class TestSerializer extends EnumSerializer {
            public TestSerializer(EnumValues v) { super(v); }
            @Override
            protected boolean _serializeAsIndex(SerializerProvider provider) { return false; }
        }
        TestSerializer testSerializer = new TestSerializer(mockEnumValues());

        JavaType enumType = Mockito.mock(JavaType.class);
        when(enumType.isEnumType()).thenReturn(true);
        when(provider.constructType(TestEnum.class)).thenReturn(enumType);

        // Act
        JsonNode result = testSerializer.getSchema(provider, TestEnum.class);

        // Assert
        assertNotNull(result);
        assertEquals("string", result.get("type").asText());
        assertTrue(result.has("enum"));
        JsonNode enumNode = result.get("enum");
        assertTrue(enumNode.isArray());
        assertEquals(3, enumNode.size());
        assertEquals("A", enumNode.get(0).asText());
        assertEquals("B", enumNode.get(1).asText());
        assertEquals("C", enumNode.get(2).asText());
    }

